%% config_template.m - Local machine configuration for the EEG tutorial pipeline.
%
% Instructions
% ------------
% 1. Copy this file to config.m.
% 2. Edit config.m for your own computer.
% 3. Do not commit config.m to GitHub, because it may contain private paths.
%
% project_root is defined by code/step0_setup.m before this file runs.

%% Data folders
% Folder containing ERP CORE N170 .set/.fdt files.
raw_dir = fullfile(project_root, 'raw_data');

% Folder for cleaned EEGLAB files generated by step2_preprocess.m.
proc_dir = fullfile(project_root, 'processed');

% Folder for generated figures, logs, and .mat result files.
results_dir = fullfile(project_root, 'results');

%% Toolbox folders
% Example format on Windows: eeglab_path = 'D:\toolboxes\eeglab';
% Example format on macOS/Linux: eeglab_path = '/path/to/eeglab';
eeglab_path = '';
fieldtrip_path = '';

%% Dataset filenames
% Example: subject '1' with pattern '%s_N170.set' becomes '1_N170.set'.
subjects = {'1', '2', '3', '4', '5', '6'};
filename_pattern = '%s_N170.set';
